/**
 * Hand Cricket Telegram Bot — single file
 *
 * SOLO : /startsolo (or /solo) -> /joinsolo -> /forcestart (or /startgame)
 *        unlimited overs, one innings, everyone bats until out, just type 0-6
 * TEAM : /team (or /startteam) -> /join_a /join_b -> /startgame
 *        -> captain buttons -> toss -> bat/bowl choice -> host /setovers (1-20)
 *        -> /bat /bowl (captains) -> type 0-6
 * TEST : /test (or /starttest) -> /team_a /team_b -> /startgame
 *        -> captains -> toss -> host picks 3-day or 6-day Test
 *        -> each day = 20 overs each side (2 innings), powerplay rules
 *        -> series winner = more day wins · pause/resume with votes
 *
 * Cards need the ./assets folder next to this file and the `sharp` package:
 *   host.jpg (solo host) · solo_final.jpg (Man of the Match) · team_final.jpg · team_banner.jpg · players_list.jpg
 * If sharp/assets are missing the bot falls back to text.
 */
require('dotenv').config();
const { Telegraf, Markup } = require('telegraf');
const { Pool } = require('pg');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const BOT_TOKEN = process.env.BOT_TOKEN;
const DATABASE_URL = process.env.DATABASE_URL;
if (!BOT_TOKEN || !DATABASE_URL) {
  console.error('Set BOT_TOKEN and DATABASE_URL');
  process.exit(1);
}

const pool = new Pool({
  connectionString: DATABASE_URL,
  ssl: DATABASE_URL.includes('supabase') ? { rejectUnauthorized: false } : undefined,
  max: 10,
  idleTimeoutMillis: 5 * 60 * 1000, // default is 10s -> every quiet moment closed the connection and the next move paid a new SSL handshake
  keepAlive: true,
  keepAliveInitialDelayMillis: 10000,
  connectionTimeoutMillis: 15000,
});
pool.on('error', (e) => console.error('pg pool error:', e.message));

const BOT_VERSION = 'r76-2026-11-03-hat-owner-host'; // shown by /testcard and in the logs so you can see which file is deployed
const bot = new Telegraf(BOT_TOKEN);
bot.use(r50Gate); // ban list + owner feedback replies (defined below)
// /Store, /SHOP, /Bat … → the command word is read in lower case
bot.use(async (ctx, next) => {
  try {
    const mm = ctx.message;
    if (mm && typeof mm.text === 'string' && mm.text.charCodeAt(0) === 47) {
      const t = mm.text.replace(/^\/[A-Za-z0-9_]+/, (s) => s.toLowerCase());
      if (t !== mm.text) mm.text = t;
    }
  } catch (_) {}
  return next();
});

bot.use((ctx, next) => { try { trackSeen(ctx); } catch (_) {} return next(); });

// per-command cooldown (spam control): a command can be reused only after 10s.
// Exempt: host, team captains, striker / non-striker / bowler of the running match, bot admins.
const CMD_CD_MS = 10000;
const cmdLast = new Map(); // `${user}:${cmd}` -> last used
const cmdWarned = new Map(); // `${user}:${cmd}` -> last warning
async function cmdCooldownExempt(ctx) {
  if (isAdmin(ctx.from.id)) return true;
  if (!ctx.chat || (ctx.chat.type !== 'group' && ctx.chat.type !== 'supergroup')) return false;
  const m = await getActiveMatch(ctx.chat.id);
  if (!m) return false;
  const uid = Number(ctx.from.id);
  if (Number(m.host_telegram_id) === uid) return true;
  const { rows: caps } = await q(`SELECT 1 FROM match_teams WHERE match_id=$1 AND captain_id=$2 LIMIT 1`, [m.id, uid]);
  if (caps.length) return true;
  const inn = await getInnings(m.id);
  if (inn) {
    for (const pid of [inn.striker_player_id, inn.non_striker_player_id, inn.current_bowler_id]) {
      if (!pid) continue;
      const p = await getPlayer(pid);
      if (p && Number(p.telegram_id) === uid) return true;
    }
  }
  return false;
}
bot.use(async (ctx, next) => {
  try {
    const t = ctx.message && ctx.message.text;
    if (t && t[0] === '/' && ctx.from) {
      const cmd = t.slice(1).split(/[\s@]/)[0].toLowerCase();
      if (cmd && !(await cmdCooldownExempt(ctx))) {
        const key = `${ctx.from.id}:${cmd}`;
        const now = Date.now();
        const last = cmdLast.get(key) || 0;
        if (now - last < CMD_CD_MS) {
          const left = Math.ceil((CMD_CD_MS - (now - last)) / 1000);
          if (now - (cmdWarned.get(key) || 0) > 3000) {
            cmdWarned.set(key, now);
            await ctx.reply(`⏳ <b>Easy there.</b> /${escapeHtml(cmd)} will be available again in <b>${left}s</b>.`, {
              parse_mode: 'HTML',
              reply_to_message_id: ctx.message.message_id,
              allow_sending_without_reply: true,
            }).catch(() => {});
          }
          return;
        }
        cmdLast.set(key, now);
        if (cmdLast.size > 5000) {
          for (const [k, v] of cmdLast) if (now - v > CMD_CD_MS) cmdLast.delete(k);
          for (const [k, v] of cmdWarned) if (now - v > CMD_CD_MS) cmdWarned.delete(k);
        }
      }
    }
  } catch (e) {
    console.error('cooldown:', e.message);
  }
  return next();
});
bot.use(async (ctx, next) => {
  const m = ctx.message;
  if (m && ctx.from && adtSessions.has(ctx.from.id) && adtSessions.get(ctx.from.id).stage !== 'review' && (m.photo || (m.document && /^image\//.test(m.document.mime_type || '')))) {
    try { await adtOnImage(ctx); } catch (e) { console.error('addt image:', e.message); await ctx.reply('Something went wrong reading that image. Try again.').catch(() => {}); }
    return;
  }
  return next();
});

// captain pressed "Set team name": the next plain message from him in the group becomes the name
const pendingTeamName = new Map(); // `${chatId}:${userId}` -> { matchId, label, at }
bot.use(async (ctx, next) => {
  try {
    const t = ctx.message && ctx.message.text;
    if (t && !t.startsWith('/') && !/^[0-6]$/.test(t.trim()) && ctx.chat && ctx.from && (ctx.chat.type === 'group' || ctx.chat.type === 'supergroup')) {
      const key = `${ctx.chat.id}:${ctx.from.id}`;
      const pend = pendingTeamName.get(key);
      if (pend) {
        pendingTeamName.delete(key);
        if (Date.now() - pend.at < 120000) {
          const nm = cleanTeamName(t);
          if (nm) {
            await q(`UPDATE match_teams SET team_name=$3 WHERE match_id=$1 AND team_label=$2`, [pend.matchId, pend.label, nm]);
            await ctx.reply(`✅ Team ${pend.label} is now *${mdEsc(nm)}*`, { parse_mode: 'Markdown', reply_to_message_id: ctx.message.message_id });
            return;
          }
        }
      }
    }
  } catch (e) {
    console.error('teamname middleware:', e.message);
  }
  return next();
});

