async function upsertUser(u) {
  await q(
    `INSERT INTO users (telegram_id, username, first_name, last_name)
     VALUES ($1,$2,$3,$4)
     ON CONFLICT (telegram_id) DO UPDATE SET
       username=COALESCE(EXCLUDED.username,users.username),
       first_name=COALESCE(EXCLUDED.first_name,users.first_name),
       last_name=COALESCE(EXCLUDED.last_name,users.last_name),
       updated_at=NOW()`,
    [u.id, u.username || null, u.first_name || null, u.last_name || null]
  );
}

// ─── Text helpers ────────────────────────────────────────
function escapeHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');
}

// plain name: first + last name preferred, else @username, else telegram id
function name(p) {
  if (!p) return '—';
  const gm = p.telegram_id != null ? genderMark(p.telegram_id) : '';
  const full = [p.first_name, p.last_name].filter(Boolean).join(' ').trim();
  if (full) return full + gm;
  if (p.username) return `@${p.username}` + gm;
  const id = p.telegram_id ?? p.id;
  const c = id != null ? nameCache.get(String(id)) : null;
  if (c) {
    const cf = [c.first_name, c.last_name].filter(Boolean).join(' ').trim();
    if (cf) return cf + gm;
    if (c.username) return `@${c.username}` + gm;
  }
  if (id != null && Number(id) > 0) resolveNameLater(id);
  return id != null ? 'Player' + gm : '—';
}
const nameCache = new Map(); // telegram_id -> { first_name, last_name, username }
const nameAsked = new Set();
function resolveNameLater(id) {
  const k = String(id);
  if (nameAsked.has(k)) return;
  nameAsked.add(k);
  Promise.resolve(bot.telegram.getChat(Number(id))).then(async (c) => {
    nameCache.set(k, { first_name: c.first_name, last_name: c.last_name, username: c.username });
    await upsertUser({ id: Number(id), username: c.username, first_name: c.first_name, last_name: c.last_name });
  }).catch(() => {});
}

// Telegram legacy-Markdown safe text (usernames contain "_" which would break parsing)
function mdEsc(value) {
  return String(value ?? '').replace(/([_*`\[])/g, '\\$1');
}
// Markdown-safe name
function mn(p) {
  return mdEsc(name(p));
}

function oversStr(balls) {
  return `${Math.floor(balls / 6)}.${balls % 6}`;
}

function isGroupOrDm(ctx) {
  return ctx.chat && ['group', 'supergroup', 'private'].includes(ctx.chat.type);
}
function isGroup(ctx) {
  return ctx.chat && (ctx.chat.type === 'group' || ctx.chat.type === 'supergroup');
}

function line(char = '─', n = 22) {
  return char.repeat(n);
}

