// ─── /bat /batting /ball /bowling (team; solo is automatic) ────────────────
// The captain can use a roster number, reply to a player's message, or tag the player.
// Without any of those the command shows the list of players (out = premium wrong sign).
async function pickPlayerArg(ctx, m, label) {
  const msg = ctx.message;
  const args = String(msg.text || '').replace(/^\/\S+\s*/, '').trim();
  const first = args.split(/\s+/)[0] || '';
  if (/^\d{1,3}$/.test(first)) return { p: await getPlayerByPos(m.id, label, parseInt(first, 10)), given: true };
  let tg = null;
  let un = null;
  for (const e of msg.entities || []) {
    if (e.type === 'text_mention' && e.user) {
      tg = e.user.id;
      break;
    }
  }
  if (!tg) {
    const mm = args.match(/@([A-Za-z0-9_]{3,32})/);
    if (mm) un = mm[1];
  }
  const rp = msg.reply_to_message;
  if (!tg && !un && rp && rp.from && !rp.from.is_bot) tg = rp.from.id;
  if (!tg && !un) return { list: true };
  const pl = await getPlayers(m.id, label);
  const p =
    pl.find(
      (x) =>
        (tg && Number(x.telegram_id) === Number(tg)) ||
        (un && x.username && String(x.username).toLowerCase() === un.toLowerCase())
    ) || null;
  return { p, given: true };
}

async function sendPickList(ctx, m, inn, kind) {
  const bat = kind === 'bat';
  const label = bat ? inn.batting_team : inn.bowling_team;
  const pl = await getPlayers(m.id, label);
  let body = '';
  if (bat) {
    const { rows } = await q(`SELECT player_id, is_out FROM batting_stats WHERE innings_id=$1`, [inn.id]);
    const out = new Set(rows.filter((r) => r.is_out).map((r) => r.player_id));
    const live = new Set([inn.striker_player_id, inn.non_striker_player_id].filter(Boolean));
    body = pl
      .map((p) => `${p.roster_position}. ${escapeHtml(shortName(p, 22))} ${out.has(p.id) ? pe('no', '❌') : live.has(p.id) ? pe('bat', '🏏') : ''}`.trimEnd())
      .join('\n');
  } else {
    const { rows } = await q(`SELECT player_id, balls_bowled FROM bowling_stats WHERE innings_id=$1`, [inn.id]);
    const balls = new Map(rows.map((r) => [r.player_id, Number(r.balls_bowled) || 0]));
    const maxB = (m.max_overs_per_bowler || MAX_BOWLER_OVERS) * 6;
    body = pl
      .map((p) => {
        const b = balls.get(p.id) || 0;
        let mark = pe('ok', '✅');
        if (b >= maxB) mark = pe('no', '❌');
        else if (inn.last_bowler_id === p.id && inn.balls_bowled % 6 === 0 && b > 0) mark = '⏳';
        else if (inn.current_bowler_id === p.id) mark = pe('bowler', '🎳');
        return `${p.roster_position}. ${escapeHtml(shortName(p, 22))} - ${Math.floor(b / 6)}.${b % 6} Ov ${mark}`;
      })
      .join('\n');
  }
  const t =
    `${bat ? pe('bat', '🏏') : pe('bowler', '🎳')} <b>${fancy(bat ? 'PICK A BATTER' : 'CHOOSE BOWLER')}</b>  <i>Team ${label}</i>\n` +
    `<blockquote>${body || '—'}</blockquote>\n` +
    `👉 Captain: <code>/${bat ? 'bat' : 'ball'} &lt;no.&gt;</code> · reply to a player · or tag`;
  await ctx.reply(t, { parse_mode: 'HTML', reply_to_message_id: ctx.message.message_id, allow_sending_without_reply: true });
}

async function batCmd(ctx) {
  if (!isGroup(ctx)) return;
  try {
    const m = await getActiveMatch(ctx.chat.id);
    if (!m || !['innings1', 'innings2'].includes(m.status)) return ctx.reply('❌ No match in progress');
    if (m.mode === 'solo') return ctx.reply('ℹ️ Solo is automatic — just type 0-6');

    let inn = await getInnings(m.id);
    if (!inn) return ctx.reply('⏳ Please wait');
    const sel = await pickPlayerArg(ctx, m, inn.batting_team);
    if (sel.list) return sendPickList(ctx, m, inn, 'bat');
    if (!['idle', 'waiting_bat'].includes(inn.ball_state)) return ctx.reply('⏳ A ball is pending');
    const team = await getTeam(m.id, inn.batting_team);
    const isHost = Number(m.host_telegram_id) === ctx.from.id;
    const isCap = Number(team?.captain_id) === ctx.from.id;
    if (!isCap && !isHost && !isAdmin(ctx.from.id))
      return ctx.reply('❌ Only the batting captain or the host can do this');

    const p = sel.p;
    if (!p) return ctx.reply('❌ Invalid player — pick someone from the batting team');
    const { rows: st } = await q(`SELECT * FROM batting_stats WHERE innings_id=$1 AND player_id=$2`, [inn.id, p.id]);
    if (st[0]?.is_out) return ctx.reply('❌ That player is already out');
    if (p.id === inn.striker_player_id || p.id === inn.non_striker_player_id)
      return ctx.reply('❌ That player is already batting');

    await q(
      `INSERT INTO batting_stats (innings_id, player_id) VALUES ($1,$2)
       ON CONFLICT (innings_id, player_id) DO NOTHING`,
      [inn.id, p.id]
    );

    let role;
    if (!inn.striker_player_id) {
      await q(`UPDATE innings SET striker_player_id=$2 WHERE id=$1`, [inn.id, p.id]);
      role = 'striker';
    } else if (!inn.non_striker_player_id) {
      await q(`UPDATE innings SET non_striker_player_id=$2 WHERE id=$1`, [inn.id, p.id]);
      role = 'non-striker';
    } else {
      await q(`UPDATE innings SET striker_player_id=$2 WHERE id=$1`, [inn.id, p.id]);
      role = 'striker';
    }

    await ctx.reply(`🏏 ${htag(p)} → <b>${role}</b>${role === 'striker' ? ' <i>(on strike)</i>' : ''}`, { parse_mode: 'HTML' });
    await sendPlayerCard(ctx.telegram, ctx.chat.id, 'bat', p);
    await sendResultGif(ctx.telegram, ctx.chat.id, 'batentry', undefined, newBatsmanCaption(p), p);
    inn = await getInnings(m.id);
    if (role === 'non-striker' && inn.striker_player_id && inn.balls_bowled === 0) {
      // both openers are in
      const striker = await getPlayer(inn.striker_player_id);
      const bowlTeam = await getTeam(m.id, inn.bowling_team);
      const cap = bowlTeam?.captain_id ? await getPlayerByTg(m.id, bowlTeam.captain_id) : null;
      await sendCaptionedGif(
        ctx.telegram,
        ctx.chat.id,
        'opener',
        `🏏 <b>OPENERS READY!</b>\n` +
          `🏃 Striker: ${htag(striker)}\n` +
          `🏏 Non-striker: ${htag(p)}\n` +
          (inn.current_bowler_id
            ? `🔥 Game on!`
            : `🎳 Bowling captain ${cap ? htag(cap) : ''}, choose your opening bowler:\n<code>/ball &lt;no.&gt;</code>`)
      );
    }
    await ensureTurnClock(m.id);
  } catch (e) {
    await ctx.reply('❌ ' + e.message);
  }
}
bot.command(['bat', 'batting'], batCmd);

async function ballCmd(ctx) {
  if (!isGroup(ctx)) return;
  try {
    const m = await getActiveMatch(ctx.chat.id);
    if (!m || !['innings1', 'innings2'].includes(m.status)) return ctx.reply('❌ No match in progress');
    if (m.mode === 'solo') return ctx.reply('ℹ️ Solo has an automatic bowler');

    const inn = await getInnings(m.id);
    if (!inn) return ctx.reply('⏳ Please wait');
    const sel = await pickPlayerArg(ctx, m, inn.bowling_team);
    if (sel.list) return sendPickList(ctx, m, inn, 'bowl');
    if (inn.ball_state !== 'idle') return ctx.reply('⏳ Please wait');
    if (!inn.striker_player_id || !inn.non_striker_player_id)
      return ctx.reply('❌ First pick 2 batsmen with /bat');

    const team = await getTeam(m.id, inn.bowling_team);
    const isHost = Number(m.host_telegram_id) === ctx.from.id;
    const isCap = Number(team?.captain_id) === ctx.from.id;
    if (!isCap && !isHost && !isAdmin(ctx.from.id))
      return ctx.reply('❌ Only the bowling captain or the host can do this');

    const p = sel.p;
    if (!p) return ctx.reply('❌ Invalid player — pick someone from the bowling team');
    const { rows: st } = await q(`SELECT * FROM bowling_stats WHERE innings_id=$1 AND player_id=$2`, [inn.id, p.id]);
    const bb = st[0]?.balls_bowled || 0;
    if (bb / 6 >= (m.max_overs_per_bowler || MAX_BOWLER_OVERS))
      return ctx.reply('❌ This bowler has completed the maximum overs');
    if (inn.last_bowler_id === p.id && inn.balls_bowled % 6 === 0 && bb > 0)
      return ctx.reply('❌ A bowler cannot bowl consecutive overs');

    await q(
      `INSERT INTO bowling_stats (innings_id, player_id) VALUES ($1,$2)
       ON CONFLICT (innings_id, player_id) DO NOTHING`,
      [inn.id, p.id]
    );
    await q(`UPDATE innings SET current_bowler_id=$2 WHERE id=$1`, [inn.id, p.id]);

    await ctx.reply(`🎳 ${htag(p)} <b>is bowling</b>`, { parse_mode: 'HTML' });
    await sendPlayerCard(ctx.telegram, ctx.chat.id, 'bowl', p);
    await sendResultGif(ctx.telegram, ctx.chat.id, 'bowlentry', undefined, newBowlerCaption(p), p);
    await ensureTurnClock(m.id);
  } catch (e) {
    await ctx.reply('❌ ' + e.message);
  }
}
bot.command(['ball', 'bowling'], ballCmd);


// ─── /call — a captain calls the whole team: one tag message in the group + a DM with a "Play Match" button ───
async function groupLinkFor(ctx, msgId) {
  try {
    const c = await ctx.telegram.getChat(ctx.chat.id);
    if (c.username) return `https://t.me/${c.username}`;
    if (c.invite_link) return c.invite_link;
  } catch (_) {}
  try {
    return await ctx.telegram.exportChatInviteLink(ctx.chat.id);
  } catch (_) {}
  return groupMsgLink(ctx.chat.id, msgId) || null;
}
bot.command('call', async (ctx) => {
  if (!isGroup(ctx)) return;
  try {
    const m = await getActiveMatch(ctx.chat.id);
    if (!m || m.mode === 'solo') return ctx.reply('❌ /call works in a team match');
    let label = null;
    for (const L of ['A', 'B']) {
      const t = await getTeam(m.id, L);
      if (t && Number(t.captain_id) === Number(ctx.from.id)) label = L;
    }
    if (!label) return ctx.reply('❌ Only a team captain can use /call');
    const pl = (await getPlayers(m.id, label)).filter((p) => Number(p.telegram_id) !== Number(ctx.from.id) && !isBotId(p.telegram_id));
    if (!pl.length) return ctx.reply('ℹ️ There is nobody to call yet');
    await ctx.reply(
      `📣 <b>Hey team members!</b>\n<blockquote><b>Your captain needs you — come on!</b></blockquote>\n${pl.map((p) => htag(p)).join(' ')}`,
      { parse_mode: 'HTML' }
    );
    const link = await groupLinkFor(ctx, ctx.message.message_id);
    const kb = link ? Markup.inlineKeyboard([[ubtn('𝗣𝗹𝗮𝘆 𝗠𝗮𝘁𝗰𝗵', link, 'bat', 'success')]]) : {};
    const who = escapeHtml(ctx.from.first_name || ctx.from.username || 'Your captain');
    for (const p of pl) {
      try {
        await ctx.telegram.sendMessage(
          Number(p.telegram_id),
          `📣 <b>${who}</b> is calling you!\n<blockquote><b>Hey team member — your captain needs you in ${escapeHtml(ctx.chat.title || 'the group')}. Come on!</b></blockquote>`,
          { parse_mode: 'HTML', ...kb }
        );
      } catch (_) {
        /* this player has not started the bot */
      }
    }
  } catch (e) {
    await ctx.reply('❌ ' + e.message);
  }
});


// Host: /penalty team a -5 abusing   OR  /penalty A -5 reason text
bot.command('penalty', async (ctx) => {
  if (!isGroup(ctx)) return;
  try {
    const m = await getActiveMatch(ctx.chat.id);
    if (!m) return ctx.reply(`${pe('no','❌')} No active match`);
    if (Number(ctx.from.id) !== Number(m.host_telegram_id) && !isAdmin(ctx.from.id))
      return ctx.reply('❌ Only the host can give penalties');
    if (m.mode === 'solo')
      return ctx.reply('❌ /penalty is for team matches. Use time-miss penalties for solo.');
    if (!['innings1', 'innings2', 'toss', 'captains', 'waiting'].includes(m.status) && m.status === 'completed')
      return ctx.reply('❌ Match already finished');

    const parts = String(ctx.message?.text || '').trim().split(/\s+/);
    // /penalty team a -5 reason...  OR /penalty A -5 reason
    let team = null;
    let amount = null;
    let reasonStart = 1;
    if (parts[1] && /^team$/i.test(parts[1]) && parts[2]) {
      team = String(parts[2]).toUpperCase().replace(/[^AB]/g, '');
      amount = Number(parts[3]);
      reasonStart = 4;
    } else if (parts[1]) {
      team = String(parts[1]).toUpperCase().replace(/[^AB]/g, '');
      amount = Number(parts[2]);
      reasonStart = 3;
    }
    if (team !== 'A' && team !== 'B')
      return ctx.reply('Usage: `/penalty team a -5 abusing`\nOr: `/penalty A -5 reason`', { parse_mode: 'Markdown' });
    if (!Number.isFinite(amount) || amount === 0)
      return ctx.reply('❌ Amount must be a non-zero number (e.g. -5 or 5). Negative = deduct runs.');
    // host said -5 → deduct 5; host said 5 → also treat as deduct 5 if positive? User said -5 so keep sign.
    // If positive, add runs (bonus); if negative, deduct.
    const delta = amount; // can be negative
    const reason = parts.slice(reasonStart).join(' ').trim() || 'host penalty';

    const inn = await getInnings(m.id);
    const trow = await getTeam(m.id, team);
    if (!trow) return ctx.reply('❌ Team not found');

    // Apply to current innings if this team is batting, else to penalty_runs (starts innings below 0)
    let applied = '';
    if (inn && inn.batting_team === team) {
      await q(`UPDATE innings SET total_runs = total_runs + $2 WHERE id=$1`, [inn.id, delta]);
      applied = `innings score ${delta >= 0 ? '+' : ''}${delta}`;
    } else {
      // store cumulative host penalty on team (penalty_runs is already used for time penalties as negative)
      await q(
        `UPDATE match_teams SET penalty_runs = COALESCE(penalty_runs,0) + $3 WHERE match_id=$1 AND team_label=$2`,
        [m.id, team, delta]
      );
      // If they already batted in a completed innings, adjust that too
      const { rows: past } = await q(
        `SELECT id FROM innings WHERE match_id=$1 AND batting_team=$2 AND is_completed=TRUE ORDER BY innings_number DESC LIMIT 1`,
        [m.id, team]
      );
      if (past[0]) {
        await q(`UPDATE innings SET total_runs = total_runs + $2 WHERE id=$1`, [past[0].id, delta]);
        applied = `completed innings ${delta >= 0 ? '+' : ''}${delta}`;
      } else {
        applied = `pre-innings penalty ${delta >= 0 ? '+' : ''}${delta} (starts from this)`;
      }
    }

    // Log note on match for scoreboard
    await q(`ALTER TABLE matches ADD COLUMN IF NOT EXISTS penalty_log TEXT`);
    const line = `Team ${team} ${delta >= 0 ? '+' : ''}${delta} (${reason})`;
    await q(
      `UPDATE matches SET penalty_log = CASE
         WHEN penalty_log IS NULL OR penalty_log = '' THEN $2
         ELSE penalty_log || E'\\n' || $2
       END WHERE id=$1`,
      [m.id, line]
    );

    await ctx.reply(
      `⚖️ *PENALTY APPLIED*\n` +
        `> Team *${team}*: *${delta >= 0 ? '+' : ''}${delta}* runs\n` +
        `> Reason: *${mdEsc(reason)}*\n` +
        `> (${mdEsc(applied)})`,
      { parse_mode: 'Markdown' }
    );
  } catch (e) {
    console.error('penalty', e);
    await ctx.reply('❌ ' + e.message);
  }
});

