async function showStoreTheme(ctx, uid, cat, idx, kind) {
  const list = STORE_CATS[cat] || [];
  if (!list.length) return;
  const i = ((idx % list.length) + list.length) % list.length;
  const theme = list[i];
  const T = THEMES[theme];
  const [owned, eq, w] = await Promise.all([ownedThemes(uid), equippedTheme(uid), walletOf(uid)]);
  const buf = await storePreviewBuf(ctx.telegram, ctx.from, uid, theme, kind);
  const status = eq === theme ? '✅ Equipped' : owned.has(theme) ? '🟢 Owned' : `💰 Price: <b>${fmtCoins(T.price)}</b> 🪙`;
  const caption =
    `🛍 <b>${escapeHtml(T.name.toUpperCase())}</b>  ·  ${cat === 'boys' ? '👦 Boys' : '👧 Girls'}  ·  ${i + 1}/${list.length}\n` +
    `${status}\n🪙 Your coins: <b>${fmtCoins(w.coins)}</b>\n<i>Preview: ${kind === 'bat' ? 'Batsman' : 'Bowler'} card with your stats</i>`;
  const act = eq === theme ? btn('✅ 𝗘𝗤𝗨𝗜𝗣𝗣𝗘𝗗', `st:x:${uid}`, null, 'success')
    : owned.has(theme) ? btn('🎽 𝗘𝗤𝗨𝗜𝗣', `st:e:${uid}:${theme}:${cat}:${i}:${kind}`, null, 'success')
    : btn(`🛒 𝗕𝗨𝗬 · ${fmtCoins(T.price)} 🪙`, `st:b:${uid}:${theme}:${cat}:${i}:${kind}`, null, 'danger');
  const other = kind === 'bat' ? 'bowl' : 'bat';
  const kb = kbOf([
    [act],
    [btn('◀ 𝗣𝗥𝗘𝗩', `st:c:${uid}:${cat}:${i - 1}:${kind}`, null, 'primary'), btn('𝗡𝗘𝗫𝗧 ▶', `st:c:${uid}:${cat}:${i + 1}:${kind}`, null, 'primary')],
    [btn(other === 'bowl' ? '🎳 𝗕𝗢𝗪𝗟𝗘𝗥 𝗩𝗜𝗘𝗪' : '🏏 𝗕𝗔𝗧𝗦𝗠𝗔𝗡 𝗩𝗜𝗘𝗪', `st:c:${uid}:${cat}:${i}:${other}`)],
    [btn('⬅ 𝗕𝗔𝗖𝗞', `st:m:${uid}`), btn('🎒 𝗜𝗡𝗩𝗘𝗡𝗧𝗢𝗥𝗬', `iv:o:${uid}`)],
  ]);
  const msg = ctx.callbackQuery && ctx.callbackQuery.message;
  if (msg && msg.photo) {
    try {
      await ctx.editMessageMedia({ type: 'photo', media: { source: buf }, caption, parse_mode: 'HTML' }, kb);
      return;
    } catch (e) {
      if (/not modified/i.test(e.message || '')) return;
    }
  }
  try { if (msg) await ctx.deleteMessage(); } catch (_) {}
  await ctx.telegram.sendPhoto(ctx.chat.id, { source: buf }, { caption, parse_mode: 'HTML', ...kb });
}

async function showStoreMenu(ctx, uid) {
  const w = await walletOf(uid);
  const msg = ctx.callbackQuery && ctx.callbackQuery.message;
  if (msg && !msg.photo) {
    try { await ctx.editMessageText(storeMenuText(w.coins), { parse_mode: 'HTML', ...storeMenuKb(uid) }); return; } catch (e) { if (/not modified/i.test(e.message || '')) return; }
  }
  try { if (msg) await ctx.deleteMessage(); } catch (_) {}
  await ctx.telegram.sendMessage(ctx.chat.id, storeMenuText(w.coins), { parse_mode: 'HTML', ...storeMenuKb(uid) });
}

async function inventoryView(uid) {
  const [owned, eq, w] = await Promise.all([ownedThemes(uid), equippedTheme(uid), walletOf(uid)]);
  const ids = ['default', ...Object.keys(THEMES).filter((t) => t !== 'default' && owned.has(t))];
  let text = `🎒 <b>INVENTORY</b>\n━━━━━━━━━━━━━━━\n🪙 Coins: <b>${fmtCoins(w.coins)}</b>\n\n<b>Card themes</b> (used for your new batsman / bowler cards)\n`;
  for (const t of ids) text += `${t === eq ? '✅' : '▫️'} ${escapeHtml(THEMES[t].name)}${THEMES[t].gender ? ` (${THEMES[t].gender})` : ''}\n`;
  text += `\nTap a theme to equip it. More themes: /store`;
  const rows = ids.map((t) => [btn(`${t === eq ? '✅ ' : ''}${THEMES[t].name}`, `iv:e:${uid}:${t}`, null, t === eq ? 'success' : 'primary')]);
  rows.push([btn('🛍 𝗦𝗧𝗢𝗥𝗘', `st:m:${uid}`)]);
  return { text, kb: kbOf(rows) };
}
