// r50: owner tools · ban · feedback · broadcast · stats · coins · MVP poster · bowling logs
// ═══════════════════════════════════════════════════════════
const OWNER_ID = 7807828008;
const OWNER2_ID = 7047624013;
const LOG_CHAT_ID = -1004397688516;
const isOwnerId = (id) => [OWNER_ID, OWNER2_ID].includes(Number(id));
const banned = new Set();
const COIN_EMOJI_IDS = ['6282611038839907352', '5008248651038852115', '6089133649897199110'];
const MVP_TPL = path.join(ASSET_DIR, 'mvp_template.jpg');
const withTimeout = (p, ms, label = 'timeout') =>
  Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error(label)), ms))]);

async function initR50() {
  for (const c of ['super_over', 'rain_mode', 'rain_used']) await q(`ALTER TABLE matches ADD COLUMN IF NOT EXISTS ${c} BOOLEAN`);
  await q(`CREATE TABLE IF NOT EXISTS banned_users (telegram_id BIGINT PRIMARY KEY, reason TEXT, banned_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await q(`CREATE TABLE IF NOT EXISTS coin_payouts (match_id TEXT NOT NULL, telegram_id BIGINT NOT NULL, amount INTEGER NOT NULL,
    PRIMARY KEY (match_id, telegram_id))`);
  await q(`CREATE TABLE IF NOT EXISTS feedback (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, chat_id BIGINT NOT NULL,
    msg_id BIGINT, owner_id BIGINT, owner_msg_id BIGINT, body TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  const { rows } = await q(`SELECT telegram_id FROM banned_users`);
  rows.forEach((r) => banned.add(Number(r.telegram_id)));
  try {
    const us = await q(`SELECT telegram_id, username, first_name, last_name FROM users`);
    us.rows.forEach((u) => nameCache.set(String(u.telegram_id), u));
  } catch (_) {}
  console.log(`r50: ${rows.length} banned users loaded`);
}

// first middleware: banned users are ignored, owner replies to feedback are delivered
async function r50Gate(ctx, next) {
  const id = ctx.from && ctx.from.id;
  if (id && !ctx.from.is_bot) nameCache.set(String(id), { first_name: ctx.from.first_name, last_name: ctx.from.last_name, username: ctx.from.username });
  if (id && banned.has(Number(id)) && !isOwnerId(id)) {
    if (ctx.callbackQuery) ctx.answerCbQuery('You are banned from this bot.', { show_alert: true }).catch(() => {});
    else if (ctx.chat && ctx.chat.type === 'private') ctx.reply('You are banned from using this bot.').catch(() => {});
    return;
  }
  const msg = ctx.message;
  if (msg && msg.reply_to_message && ctx.chat && ctx.chat.type === 'private' && isOwnerId(id) && !String(msg.text || '').startsWith('/')) {
    try {
      if (await feedbackReply(ctx)) return;
    } catch (e) {
      console.error('feedback reply:', e.message);
    }
  }
  return next();
}

const ownerOnly = (fn) => async (ctx, next) => {
  if (!ctx.from || !isOwnerId(ctx.from.id)) return;
  try {
    return await fn(ctx, next);
  } catch (e) {
    console.error('owner cmd:', e.message);
    ctx.reply('Error: ' + e.message).catch(() => {});
  }
};
const cmdArgs = (ctx) => String(ctx.message.text || '').replace(/^\/\w+(@\w+)?\s*/, '').trim();

// target = replied user, numeric id or @username ; returns { id, rest }
async function resolveOwnerTarget(ctx) {
  const rep = ctx.message.reply_to_message;
  const parts = cmdArgs(ctx).split(/\s+/).filter(Boolean);
  if (rep && rep.from && !rep.from.is_bot) return { id: rep.from.id, rest: parts };
  if (!parts.length) return null;
  const a = parts[0];
  if (/^-?\d{5,}$/.test(a)) return { id: Number(a), rest: parts.slice(1) };
  if (/^@?\w{3,}$/.test(a)) {
    const { rows } = await q(`SELECT telegram_id FROM users WHERE LOWER(username)=LOWER($1) LIMIT 1`, [a.replace('@', '')]);
    if (rows[0]) return { id: Number(rows[0].telegram_id), rest: parts.slice(1) };
  }
  return null;
}

// ── coins ──
async function addCoins(id, n) {
  await walletOf(id);
  const { rows } = await q(
    `UPDATE wallets SET coins = GREATEST(0, coins + $2), updated_at = NOW() WHERE telegram_id=$1 RETURNING coins`,
    [id, n]
  );
  return Number(rows[0].coins);
}
// premium coin emojis + bold username + "won the MONSTER COINS" (sent to the user's DM only)
async function dmCoins(telegram, p, amount, extra = '', toChat = null) {
  const nm = p.username ? String(p.username) : videoName(p);
  const ents = [];
  let text = '';
  for (const eid of COIN_EMOJI_IDS) {
    ents.push({ type: 'custom_emoji', offset: text.length, length: 2, custom_emoji_id: eid });
    text += '🪙';
  }
  text += ' ';
  ents.push({ type: 'bold', offset: text.length, length: nm.length });
  text += nm + ' won the MONSTER COINS';
  const amt = `+${amount}`;
  text += '\n';
  ents.push({ type: 'bold', offset: text.length, length: amt.length });
  text += amt + (extra ? ` · ${extra}` : '');
  try {
    await telegram.callApi('sendMessage', { chat_id: toChat || Number(p.telegram_id), text, entities: ents });
  } catch (e) {
    /* user has not started the bot: no DM possible */
  }
}
async function matchPerf(matchId) {
  const { rows } = await q(
    `SELECT mp.id, mp.match_id, mp.telegram_id, mp.username, mp.first_name, mp.last_name, mp.team_label,
            COALESCE(b.runs,0)::int AS runs, COALESCE(w.wkts,0)::int AS wkts
       FROM match_players mp
       LEFT JOIN (SELECT bs.player_id, SUM(bs.runs) AS runs FROM batting_stats bs JOIN innings i ON i.id=bs.innings_id
                   WHERE i.match_id=$1 GROUP BY bs.player_id) b ON b.player_id=mp.id
       LEFT JOIN (SELECT bw.player_id, SUM(bw.wickets) AS wkts FROM bowling_stats bw JOIN innings i ON i.id=bw.innings_id
                   WHERE i.match_id=$1 GROUP BY bw.player_id) w ON w.player_id=mp.id
      WHERE mp.match_id=$1`,
    [matchId]
  );
  return fillNames(rows);
}
// after a finished match: 40 / 100 by performance, 150 for the Man of the Match (once per player per match)
async function payMatchCoins(telegram, m, aw) {
  const rows = await matchPerf(m.id);
  const motmId = aw && aw.motm ? Number(aw.motm.telegram_id) : null;
  for (const p of rows) {
    const tid = Number(p.telegram_id);
    if (!(tid > 0)) continue;
    const isMotm = motmId === tid;
    const amt = isMotm ? 150 : Number(p.runs) >= 20 || Number(p.wkts) >= 2 ? 100 : 40;
    const ins = await q(
      `INSERT INTO coin_payouts (match_id, telegram_id, amount) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING RETURNING 1`,
      [m.id, tid, amt]
    );
    if (!ins.rows.length) continue;
    await addCoins(tid, amt);
    await dmCoins(telegram, p, amt, isMotm ? 'Man of the Match' : '');
    if (isMotm && Number(m.group_chat_id) < 0) await dmCoins(telegram, p, amt, 'Man of the Match', Number(m.group_chat_id));
  }
}
// match stopped while live: everybody gets 40 and the scoreboard is shown
async function forfeitPayout(telegram, groupId, m) {
  try {
    if (!m || !/^innings|^live|^paused/.test(String(m.status || ''))) return;
    try { await sendLong(telegram, groupId, await fullScorecard(m.id)); } catch (_) {}
    const rows = await matchPerf(m.id);
    for (const p of rows) {
      const tid = Number(p.telegram_id);
      if (!(tid > 0)) continue;
      const ins = await q(
        `INSERT INTO coin_payouts (match_id, telegram_id, amount) VALUES ($1,$2,40) ON CONFLICT DO NOTHING RETURNING 1`,
        [m.id, tid]
      );
      if (!ins.rows.length) continue;
      await addCoins(tid, 40);
      await dmCoins(telegram, p, 40, 'forfeit');
    }
  } catch (e) {
    console.error('forfeitPayout:', e.message);
  }
}

// ── bowling log → LOG_CHAT_ID only ──
const chatTitleCache = new Map();
async function chatTitle(telegram, id) {
  if (chatTitleCache.has(id)) return chatTitleCache.get(id);
  let t = String(id);
  try { t = (await telegram.getChat(id)).title || t; } catch (_) {}
  chatTitleCache.set(id, t);
  return t;
}
async function sendBowlLog(telegram, m, inn, overNo) {
  const { rows } = await q(
    `SELECT d.bowler_id, d.ball_number, d.runs_scored, d.is_wicket, mp.username, mp.first_name, mp.last_name, mp.telegram_id
       FROM deliveries d LEFT JOIN match_players mp ON mp.id=d.bowler_id
      WHERE d.innings_id=$1 AND d.over_number=$2 ORDER BY d.ball_number`,
    [inn.id, overNo]
  );
  if (!rows.length) return;
  const title = await chatTitle(telegram, Number(m.group_chat_id));
  const by = new Map();
  for (const r of rows) {
    const k = String(r.bowler_id);
    if (!by.has(k)) by.set(k, { p: r, balls: [], runs: 0, w: 0 });
    const o = by.get(k);
    o.balls.push(r.is_wicket ? 'W' : String(r.runs_scored));
    o.runs += Number(r.runs_scored) || 0;
    if (r.is_wicket) o.w++;
  }
  let t = `<b>${escapeHtml(title)}</b>\nMatch ${escapeHtml(String(m.id).slice(-6))} · Team ${escapeHtml(String(inn.bowling_team))} bowling · Over ${overNo}\n`;
  for (const o of by.values()) {
    t += `\n<b>${escapeHtml(videoName(o.p))}</b> bowled ${o.balls.length} ball${o.balls.length === 1 ? '' : 's'}\n` +
      `Balls: ${o.balls.join(' · ')}\nRuns: ${o.runs} · Wickets: ${o.w}`;
  }
  await telegram.sendMessage(LOG_CHAT_ID, t, { parse_mode: 'HTML' });
}

