async function knownGroups() {
  const { rows } = await q(
    `SELECT DISTINCT chat_id::bigint AS id FROM (
       SELECT group_chat_id AS chat_id FROM matches WHERE group_chat_id < 0
       UNION SELECT chat_id FROM group_settings WHERE chat_id < 0) x`
  );
  return rows.map((r) => Number(r.id));
}
bot.command('stats', ownerOnly(async (ctx) => {
  if (ctx.chat.type !== 'private') return;
  const groups = await knownGroups();
  const u = await q(`SELECT COUNT(*)::int AS n FROM users WHERE telegram_id > 0`);
  const mt = await q(`SELECT COUNT(*)::int AS n FROM matches`);
  const live = await q(`SELECT COUNT(*)::int AS n FROM matches WHERE status NOT IN ('completed','cancelled')`);
  return ctx.reply(`Total groups: ${groups.length}\nTotal users: ${u.rows[0].n}\nTotal matches: ${mt.rows[0].n}\nLive matches: ${live.rows[0].n}`);
}));
bot.command('gstats', ownerOnly(async (ctx) => {
  if (ctx.chat.type !== 'private') return;
  const groups = await knownGroups();
  const lines = new Array(groups.length);
  let next = 0;
  const worker = async () => {
    while (next < groups.length) {
      const i = next++;
      const id = groups[i];
      try {
        const c = await ctx.telegram.getChat(id);
        let cnt = '?';
        try { cnt = await ctx.telegram.callApi('getChatMemberCount', { chat_id: id }); } catch (_) {}
        const link = c.username ? `https://t.me/${c.username}` : c.invite_link || `id ${id}`;
        lines[i] = `${i + 1}. ${c.title || id} | ${cnt} members | ${link}`;
      } catch (_) {
        lines[i] = `${i + 1}. (bot removed) | id ${id}`;
      }
    }
  };
  await Promise.all(Array.from({ length: 6 }, worker));
  let buf = `Groups: ${groups.length}\n`;
  for (const l of lines) {
    if (buf.length + l.length > 3800) { await ctx.reply(buf, { disable_web_page_preview: true }); buf = ''; }
    buf += l + '\n';
  }
  if (buf.trim()) await ctx.reply(buf, { disable_web_page_preview: true });
}));
// /broadcast [groups|users] <your text>   or reply to any message with /broadcast
bot.command('broadcast', ownerOnly(async (ctx) => {
  let args = cmdArgs(ctx);
  let scope = 'all';
  const m1 = args.match(/^(groups|users|all)\b\s*/i);
  if (m1) { scope = m1[1].toLowerCase(); args = args.slice(m1[0].length); }
  const rep = ctx.message.reply_to_message;
  if (!rep && !args) return ctx.reply('Usage: /broadcast [groups|users] <text>  or reply to a message with /broadcast');
  let targets = [];
  if (scope !== 'users') targets.push(...(await knownGroups()));
  if (scope !== 'groups') targets.push(...(await q(`SELECT telegram_id FROM users WHERE telegram_id > 0`)).rows.map((r) => Number(r.telegram_id)));
  targets = [...new Set(targets)].filter((id) => !banned.has(id));
  await ctx.reply(`Broadcasting to ${targets.length} chats…`);
  let ok = 0, fail = 0;
  for (const id of targets) {
    try {
      if (rep) await ctx.telegram.copyMessage(id, ctx.chat.id, rep.message_id);
      else await ctx.telegram.sendMessage(id, args, { disable_web_page_preview: true });
      ok++;
    } catch (_) { fail++; }
    await sleep(60);
  }
  return ctx.reply(`Broadcast done. Delivered: ${ok} · Failed: ${fail}`);
}));

// ── /feedback: user → owner DM → owner's reply goes back into the user's chat ──
bot.command('feedback', async (ctx) => {
  const body = cmdArgs(ctx) || String(ctx.message.reply_to_message?.text || '').trim();
  if (!body) return ctx.reply('Usage: /feedback <your message>', { reply_to_message_id: ctx.message.message_id });
  const u = ctx.from;
  const { rows } = await q(
    `INSERT INTO feedback (user_id, chat_id, msg_id, owner_id, body) VALUES ($1,$2,$3,$4,$5) RETURNING id`,
    [u.id, ctx.chat.id, ctx.message.message_id, OWNER_ID, body.slice(0, 3500)]
  );
  const fid = rows[0].id;
  const where = ctx.chat.type === 'private' ? 'DM' : `${ctx.chat.title || ''} (${ctx.chat.id})`;
  const nm = [u.first_name, u.last_name].filter(Boolean).join(' ') || u.username || String(u.id);
  try {
    const sent = await ctx.telegram.sendMessage(
      OWNER_ID,
      `<b>Feedback #${fid}</b>\nFrom: <a href="tg://user?id=${u.id}">${escapeHtml(nm)}</a> (<code>${u.id}</code>${u.username ? ' @' + escapeHtml(u.username) : ''})\n` +
        `Chat: ${escapeHtml(where)}\n\n${escapeHtml(body)}\n\n<i>Reply to this message to answer.</i>`,
      { parse_mode: 'HTML' }
    );
    await q(`UPDATE feedback SET owner_msg_id=$2 WHERE id=$1`, [fid, sent.message_id]);
    return ctx.reply('Thanks! Your feedback was sent to the owner.', { reply_to_message_id: ctx.message.message_id });
  } catch (e) {
    console.error('feedback to owner:', e.message);
    return ctx.reply('Could not reach the owner right now. Please try again later.', { reply_to_message_id: ctx.message.message_id });
  }
});
async function feedbackReply(ctx) {
  const rid = ctx.message.reply_to_message.message_id;
  const { rows } = await q(`SELECT * FROM feedback WHERE owner_msg_id=$1 AND owner_id=$2 LIMIT 1`, [rid, ctx.chat.id]);
  const f = rows[0];
  if (!f) return false;
  const opts = { reply_to_message_id: Number(f.msg_id), allow_sending_without_reply: true };
  try {
    if (ctx.message.text) {
      await ctx.telegram.sendMessage(Number(f.chat_id), `<b>Reply from the owner</b>\n${escapeHtml(ctx.message.text)}`, { ...opts, parse_mode: 'HTML' });
    } else {
      await ctx.telegram.copyMessage(Number(f.chat_id), ctx.chat.id, ctx.message.message_id, opts);
    }
    await ctx.reply(`Reply delivered (feedback #${f.id}).`);
  } catch (e) {
    await ctx.reply(`Could not deliver: ${e.message}`);
  }
  return true;
}

// ═══ LEADERBOARD: MVP poster + paged boards (Back / Next) ═══
async function mvpTop(groupId) {
  const g = groupId ? 'AND m.group_chat_id=$1' : '';
  const params = groupId ? [groupId] : [];
  const j = (tbl, alias) =>
    `FROM ${tbl} ${alias} JOIN match_players mp ON mp.id=${alias}.player_id JOIN innings i ON i.id=${alias}.innings_id JOIN matches m ON m.id=i.match_id
      WHERE m.status='completed' AND mp.telegram_id > 0 ${g}`;
  const { rows } = await q(
    `WITH bt AS (SELECT mp.telegram_id AS id, SUM(bs.runs)::int AS runs ${j('batting_stats', 'bs')} GROUP BY mp.telegram_id),
          bw AS (SELECT mp.telegram_id AS id, SUM(w.wickets)::int AS wkts ${j('bowling_stats', 'w')} GROUP BY mp.telegram_id)
     SELECT COALESCE(bt.id, bw.id) AS id, COALESCE(bt.runs,0) AS runs, COALESCE(bw.wkts,0) AS wkts
       FROM bt FULL JOIN bw ON bt.id = bw.id
      ORDER BY COALESCE(bt.runs,0) + 20*COALESCE(bw.wkts,0) DESC, COALESCE(bt.runs,0) DESC LIMIT 15`,
    params
  );
  if (!rows.length) return [];
  const { rows: us } = await q(`SELECT telegram_id, username, first_name, last_name FROM users WHERE telegram_id = ANY($1::bigint[])`, [rows.map((r) => Number(r.id))]);
  const um = new Map(us.map((u) => [Number(u.telegram_id), u]));
  return rows.map((r) => ({
    id: Number(r.id), runs: Number(r.runs), wkts: Number(r.wkts),
    name: videoName(um.get(Number(r.id)) || { telegram_id: r.id }),
  }));
}
async function renderMvpPoster(list) {
  needSharp();
  if (!fs.existsSync(MVP_TPL)) return null;
  const layers = [];
  for (let i = 0; i < Math.min(15, list.length); i++) {
    const cy = 414 + i * 52.55;
    const r = list[i];
    const nm = await fitText(r.name.toUpperCase(), 30, 420, '#ffffff', 16);
    layers.push({ input: nm.data, left: 160, top: Math.round(cy - nm.info.height / 2) });
    layers.push(centered(await fitText(String(r.runs), 30, 190, '#ffd34d', 16), 790, cy));
    layers.push(centered(await fitText(String(r.wkts), 30, 170, '#ffffff', 16), 1090, cy));
  }
  return sharp(MVP_TPL).composite(layers).jpeg({ quality: 90 }).toBuffer();
}
const LB_PAGES_ALL = ['mvp:a', 'runs:a', 'wkts:a', 'high:a', 'best:a'];
const LB_PAGES_GC = ['mvp:a', 'mvp:g', 'runs:a', 'runs:g', 'wkts:a', 'wkts:g', 'high:a', 'high:g', 'best:a', 'best:g'];
const lbPages = (inGroup) => (inGroup ? LB_PAGES_GC : LB_PAGES_ALL);
function lbPageKb(idx, pages) {
  const n = pages.length;
  return Markup.inlineKeyboard([
    [btn('𝗕𝗔𝗖𝗞', `lbp:${(idx - 1 + n) % n}`, 'door', 'danger'), btn(`${idx + 1}/${n}`, 'lbp:noop'), btn('𝗡𝗘𝗫𝗧', `lbp:${(idx + 1) % n}`, 'trophy', 'success')],
  ]);
}
async function lbPageContent(page, chat, inGroup) {
  const [cat, scope] = page.split(':');
  const groupId = scope === 'g' && inGroup ? chat.id : null;
  if (cat === 'mvp') {
    const list = await mvpTop(groupId);
    const title = `MVP PLAYERS — ${groupId ? (chat.title || 'THIS GROUP').toUpperCase() : 'ALL TIME'}`;
    let cap = `<b>${escapeHtml(title)}</b>\n`;
    if (!list.length) cap += 'No data yet — play some matches!';
    list.forEach((r, i) => { cap += `${i + 1}. ${escapeHtml(r.name)} — ${r.runs} runs · ${r.wkts} wkts\n`; });
    let img = null;
    try { img = list.length ? await renderMvpPoster(list) : null; } catch (e) { console.error('mvp poster:', e.message); }
    return { photo: img, html: cap };
  }
  const text = await lbText(cat, groupId, inGroup ? chat.title : null);
  return { photo: null, html: stripPe(md2html(text)) };
}
async function showLbPage(ctx, idx) {
  const inGroup = ctx.chat && (ctx.chat.type === 'group' || ctx.chat.type === 'supergroup');
  const pages = lbPages(inGroup);
  idx = ((Number(idx) || 0) % pages.length + pages.length) % pages.length;
  const c = await lbPageContent(pages[idx], ctx.chat, inGroup);
  const kb = lbPageKb(idx, pages);
  let cap = c.html;
  if (cap.length > 1000) cap = cap.slice(0, 1000).replace(/\n[^\n]*$/, '');
  const file = c.photo ? c.photo : fs.existsSync(START_BANNER) ? fs.readFileSync(START_BANNER) : null;
  if (!file) return ctx.telegram.sendMessage(ctx.chat.id, c.html, { parse_mode: 'HTML', ...kb });
  if (ctx.callbackQuery && ctx.callbackQuery.message && ctx.callbackQuery.data && ctx.callbackQuery.data.startsWith('lbp:')) {
    try {
      // same message is edited in place (no delete / re-send)
      return await ctx.editMessageMedia({ type: 'photo', media: { source: file }, caption: cap, parse_mode: 'HTML' }, kb);
    } catch (e) {
      if (/not modified/i.test(e.message || '')) return;
      console.error('lb edit failed:', e.message);
    }
  }
  return ctx.telegram.sendPhoto(ctx.chat.id, { source: file }, { caption: cap, parse_mode: 'HTML', ...kb });
}

