const MINIAPP_HTML_B64 = '';

// ─── Mini app (Telegram Web App) server ───────────────────────────────────────
// Runs inside the bot process (no extra packages). Listens on 127.0.0.1:MINIAPP_PORT (default 3000);
// put a Cloudflare Tunnel / reverse proxy in front of it and give that https URL to BotFather.
const http = require('http');
const MINI_PORT = Number(process.env.MINIAPP_PORT || 3000);
const MINI_ZONE_URL = process.env.PLAYZONE_URL || 'https://t.me/+ouAM8opQ0k1jMjg1';
const MINI_SUPPORT_URL = process.env.SUPPORT_URL || 'https://t.me/darkwavenv';
const MINI_DEV = process.env.MINIAPP_DEV === '1'; // only for testing in a normal browser: /?dev=<telegram id>
const MINI_HTML = Buffer.from(MINIAPP_HTML_B64, 'base64');

function miniVerify(initData) {
  try {
    if (!initData) return null;
    const p = new URLSearchParams(initData);
    const hash = p.get('hash');
    if (!hash) return null;
    p.delete('hash');
    const dcs = [...p.entries()].map(([k, v]) => `${k}=${v}`).sort().join('\n');
    const secret = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
    const calc = crypto.createHmac('sha256', secret).update(dcs).digest('hex');
    if (calc.length !== hash.length || !crypto.timingSafeEqual(Buffer.from(calc), Buffer.from(hash))) return null;
    const age = Date.now() / 1000 - Number(p.get('auth_date') || 0);
    if (!(age < 7 * 24 * 3600)) return null;
    const u = JSON.parse(p.get('user') || 'null');
    return u && u.id ? u : null;
  } catch (_) { return null; }
}
function miniUser(req, url) {
  const u = miniVerify(req.headers['x-tg-init']);
  if (u) return u;
  if (MINI_DEV && url.searchParams.get('dev')) return { id: Number(url.searchParams.get('dev')), first_name: 'Dev', username: 'dev' };
  return null;
}
async function miniNames(ids) {
  const out = new Map();
  ids = [...new Set(ids.map(Number).filter((x) => x > 0))];
  if (!ids.length) return out;
  try {
    const { rows } = await q(`SELECT telegram_id, username, first_name, last_name FROM users WHERE telegram_id = ANY($1::bigint[])`, [ids]);
    for (const r of rows) out.set(Number(r.telegram_id), r);
  } catch (_) {}
  const res = new Map();
  for (const id of ids) {
    const r = out.get(id) || nameCache.get(String(id)) || {};
    const full = [r.first_name, r.last_name].filter(Boolean).join(' ').trim();
    res.set(id, { name: (full || (r.username ? '@' + r.username : 'Player')).slice(0, 26), username: r.username || null });
  }
  return res;
}
const MINI_CATS = ['overall', 'runs', 'wkts', 'wins', 'matches', 'hundreds', 'fifties', 'hattricks', 'potm', 'streak', 'wealthy'];
function miniTier(rank, total) {
  if (!rank || !total) return 'Unranked';
  const p = (rank / total) * 100;
  return p <= 1 ? 'Legend' : p <= 5 ? 'Elite' : p <= 15 ? 'Master' : p <= 35 ? 'Pro' : p <= 70 ? 'Rising' : 'Rookie';
}
